package com.airesumebuilder.feature.pdf.service;import com.airesumebuilder.feature.pdf.repository.PdfExportRepository;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PdfService{private final PdfExportRepository repository;private final PdfRenderer renderer;public PdfService(PdfExportRepository r,PdfRenderer p){repository=r;renderer=p;}@Transactional public GeneratedPdf generate(String email,long resumeId){var resume=repository.resume(email,resumeId);byte[] bytes=renderer.render(resume);String name=safeName(resume.title())+".pdf";repository.record(resume,name,bytes.length,sha(bytes));return new GeneratedPdf(name,bytes);}@Transactional(readOnly=true)public List<PdfExportRepository.Export>history(String email,long resumeId){repository.resume(email,resumeId);return repository.history(email,resumeId);}private String safeName(String s){String v=s==null?"resume":s.replaceAll("[^a-zA-Z0-9._-]+","-").replaceAll("^-|-$","");return v.isBlank()?"resume":v;}private String sha(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}public record GeneratedPdf(String fileName,byte[]content){} }
